class Solution:
    def splitLoad(self, loads: list[int], groups: int) -> int:
        lower, upper = max(loads), sum(loads)
        while lower < upper:
            bound = (lower + upper) // 2
            used, running = 1, 0
            for load in loads:
                if running + load > bound:
                    used += 1
                    running = 0
                running += load
            if used <= groups:
                upper = bound
            else:
                lower = bound + 1
        return lower
